#!/usr/bin/env python3
"""Transparent assumption-based planning model; never presented as observed causal lift."""
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'data'/'processed'; DOCS=ROOT/'docs'; REPORTS=ROOT/'reports'
DOCS.mkdir(exist_ok=True); REPORTS.mkdir(exist_ok=True)
monthly=pd.read_csv(OUT/'monthly_recovery_metrics.csv')
complete=monthly.loc[~monthly['partial_month'].astype(bool)]
base_monthly=float(complete['recovered_amount'].mean())
annualized=base_monthly*12
TARGETABLE_SHARE=0.70
INVESTMENT=100_000_000.0 # ₹10 Cr
REALIZATION=0.85 # finance planning assumption; fraction of incremental collections treated as economic benefit
scenarios=[('Downside',0.05),('Base case',0.10),('Upside',0.15)]
rows=[]
for name,lift in scenarios:
    targetable=annualized*TARGETABLE_SHARE
    incremental=targetable*lift
    realized=incremental*REALIZATION
    net=realized-INVESTMENT
    roi=net/INVESTMENT*100
    rows.append({'scenario':name,'annualized_observed_cash_inr':round(annualized,2),'targetable_share_assumption_pct':TARGETABLE_SHARE*100,'targetable_cash_base_inr':round(targetable,2),'incremental_lift_assumption_pct':lift*100,'incremental_gross_recovery_inr':round(incremental,2),'benefit_realization_factor_assumption_pct':REALIZATION*100,'realized_economic_benefit_inr':round(realized,2),'investment_inr':INVESTMENT,'net_benefit_after_investment_inr':round(net,2),'planning_roi_pct':round(roi,2),'break_even_gross_incremental_recovery_inr':round(INVESTMENT/REALIZATION,2),'break_even_lift_on_targetable_base_pct':round(INVESTMENT/REALIZATION/targetable*100,2),'classification':'ASSUMPTION-BASED SCENARIO; NOT MEASURED CAUSAL LIFT'})
pd.DataFrame(rows).to_csv(OUT/'investment_roi_scenarios.csv',index=False)
# DQ/cleaning impact values based on current generated artifacts
p=pd.read_csv(OUT/'payments_canonical.csv')
raw=pd.read_csv(ROOT/'data'/'raw'/'payments.csv',low_memory=False)
raw_success=float(pd.to_numeric(raw.loc[raw.payment_status.astype(str).str.upper().str.strip().eq('SUCCESS'),'amount'],errors='coerce').fillna(0).sum())
canonical_cash=float(p['effective_recovered_amount'].sum())
metrics=[
('Raw payment rows',len(raw),'Rows before deduplication'),
('After payment_id deduplication',int(raw.payment_id.nunique()),'Unique payment IDs; some IDs may have status/event updates'),
('Canonical transaction-reference events',len(p),'Latest canonical event per reference; missing references use payment-ID surrogate'),
('Rows removed between raw and canonical',len(raw)-len(p),'Net reduction; not every removed row is necessarily erroneous'),
('Raw SUCCESS amount before canonicalization (INR)',round(raw_success,2),'Inflated/uncanonicalized comparison, not an approved ledger total'),
('Canonical effective SUCCESS cash (INR)',round(canonical_cash,2),'Only final canonical SUCCESS amounts contribute'),
('Raw SUCCESS minus canonical cash (INR)',round(raw_success-canonical_cash,2),'Difference caused by event/reference/status canonicalization; Finance reconciliation required'),
('Canonical event reduction (%)',round((len(raw)-len(p))/len(raw)*100,2),'Reduction relative to raw payment rows'),
('Cash amount reduction (%)',round((raw_success-canonical_cash)/raw_success*100,2) if raw_success else 0,'Comparison of raw SUCCESS rows vs canonical effective cash; not automatically an error rate'),
('Golden account-month rows',len(pd.read_csv(OUT/'golden_dataset_account_month.csv')),'Account × observed month spine'),
('Golden account-month duplicate keys',int(pd.read_csv(OUT/'golden_dataset_account_month.csv').duplicated(['account_id','month']).sum()),'Expected zero'),
]
pd.DataFrame(metrics,columns=['measure','value','interpretation']).to_csv(OUT/'cleaning_impact_summary.csv',index=False)
# Generate styled HTML DQ report with concrete impact table
impact=pd.DataFrame(metrics,columns=['measure','value','interpretation'])
qa_path=OUT/'data_quality_acceptance_checks.csv'
qa_checks=pd.read_csv(qa_path) if qa_path.exists() else pd.DataFrame(columns=['check_id','area','severity','check','observed','threshold','status','business_impact','action'])
def fmt(v):
    if isinstance(v,float): return f'{v:,.2f}'
    return f'{v:,}' if isinstance(v,int) else str(v)
trs=''.join(f'<tr><td>{r.measure}</td><td class="num">{fmt(r.value)}</td><td>{r.interpretation}</td></tr>' for r in impact.itertuples())
qa_trs=''.join(f'<tr><td>{r.check_id}</td><td>{r.area}</td><td>{r.check}</td><td>{r.observed}</td><td>{r.threshold}</td><td class="status {str(r.status).lower()}">{r.status}</td><td>{r.action}</td></tr>' for r in qa_checks.itertuples())
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Golden Dataset, Data Quality & Cleaning Impact</title><link rel="stylesheet" href="data_quality_report.css"></head><body><header><p class="eyebrow">COLLECTIONS RECOVERY ANALYTICS · DATA TRUST</p><h1>Golden Dataset & Data Quality</h1><p>What was cleaned, why it matters, and what still needs source-owner approval.</p><span class="pill">Reproducible · Synthetic seed 42</span></header><main><section class="cards"><article><small>Golden dataset</small><strong>{len(pd.read_csv(OUT/'golden_dataset_account_month.csv')):,}</strong><p>{pd.read_csv(OUT/'golden_dataset_account_month.csv').account_id.nunique():,} accounts × {pd.read_csv(OUT/'golden_dataset_account_month.csv').month.nunique()} observed periods</p></article><article><small>Canonical payment events</small><strong>{len(p):,}</strong><p>From {len(raw):,} raw payment rows</p></article><article><small>Net row reduction</small><strong>{(len(raw)-len(p))/len(raw)*100:.2f}%</strong><p>Canonicalization, not a blanket error rate</p></article></section><section class="panel"><h2>Cleaning impact quantified</h2><p>Counts and amounts below are regenerated from the raw inputs and current pipeline output. A raw-versus-canonical difference is an audit signal; Finance must reconcile it before it is treated as a confirmed overstatement.</p><div class="table-wrap"><table><thead><tr><th>Measure</th><th>Value</th><th>Interpretation / business impact</th></tr></thead><tbody>{trs}</tbody></table></div></section><section class="panel"><h2>Data-quality acceptance checks</h2><p>Checks are generated from the current pipeline. REVIEW indicates a source-policy decision is required; it is not silently treated as PASS.</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Area</th><th>Check</th><th>Observed</th><th>Threshold</th><th>Status</th><th>Action</th></tr></thead><tbody>{qa_trs}</tbody></table></div><p><b>Status counts:</b> {qa_checks.status.value_counts().to_dict()}</p></section><section class="panel"><h2>Golden Dataset grain and contract</h2><ul><li><b>Grain:</b> one row per canonical account × observed month.</li><li><b>Key:</b> <code>(account_id, month)</code>; must be unique.</li><li><b>Payment rule:</b> latest event per payment ID, then latest per transaction reference; blank references use a payment-ID surrogate.</li><li><b>Cash rule:</b> only final <code>SUCCESS</code> events contribute; failed, pending and reversed statuses contribute zero.</li><li><b>Lineage:</b> raw CSVs are preserved; canonical outputs and checks are regenerated by <code>python src/run_all.py</code>.</li></ul></section><section class="panel warning"><h2>Do not mistake a technical rule for source truth</h2><ul><li>3,407 conflicting transaction-reference groups were flagged in the forensic output; source-ledger adjudication is required.</li><li>Timezone semantics, vendor disposition crosswalks and agent identity conflicts require source-owner confirmation.</li><li>The available snapshot outstanding balance is not a historical month-opening denominator; recovery-rate trend remains unvalidated.</li><li>Cleaning impact shows how the chosen rule changes results, not that every removed amount was fraudulent or invalid.</li></ul></section><section class="panel"><h2>Reproducibility and acceptance checks</h2><p>Run <code>python src/run_all.py</code> then <code>pytest -q</code>. Before production, reconcile canonical payment events and net cash to Finance’s ledger and sign off the tie-break rule for same-time conflicts.</p><p class="foot">This report separates measured pipeline output from unresolved business definitions.</p></section></main></body></html>'''
(REPORTS/'data_quality_report.html').write_text(html,encoding='utf-8')
print(f'Investment scenarios and cleaning impact generated. Annualized observed cash baseline ₹{annualized/1e7:.2f} Cr (simple annualization of seven completed months).')
# Styled, standalone business case report
sc=pd.DataFrame(rows)
scenario_rows=''.join(f'<tr><td><b>{r.scenario}</b></td><td>{r.incremental_lift_assumption_pct:.0f}%</td><td>₹{r.incremental_gross_recovery_inr/1e7:.2f} Cr</td><td>₹{r.realized_economic_benefit_inr/1e7:.2f} Cr</td><td class="{"positive" if r.planning_roi_pct>=0 else "negative"}">{r.planning_roi_pct:.1f}%</td><td>₹{r.net_benefit_after_investment_inr/1e7:.2f} Cr</td></tr>' for r in sc.itertuples())
base=sc.loc[sc.scenario.eq('Base case')].iloc[0]
report=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>₹10 Cr Investment Case | Collections Recovery Analytics</title><link rel="stylesheet" href="investment_business_case.css"></head><body><header><p class="eyebrow">EXECUTIVE DECISION · ASSUMPTION-BASED MODEL</p><h1>Winning investment hypothesis: Better borrower targeting</h1><p>₹10 Cr planning case, scenario range, break-even hurdle, and randomized pilot to validate actual incremental lift.</p><span class="pill">Not measured causal ROI</span></header><main><section class="hero-grid"><article><small>Recommended area to test</small><strong>Better borrower targeting</strong><p>Best first candidate for a measurable, stratified experiment; not proven winner from observational data.</p></article><article><small>Base-case planning ROI</small><strong>{base.planning_roi_pct:.1f}%</strong><p>Scenario result under explicit assumptions, not an observed or statistically estimated return.</p></article><article><small>Gross incremental cash to break even</small><strong>₹{base.break_even_gross_incremental_recovery_inr/1e7:.2f} Cr</strong><p>At the assumed 85% economic-benefit realization factor.</p></article></section><section class="panel"><h2>Why borrower targeting is the leading hypothesis</h2><p>The observed seven-day payment association varies by recommended channel, but differences are small and non-randomized. This cannot prove a winning channel. Better targeting is selected as the <b>first investment hypothesis to test</b> because it can be evaluated against a randomized holdout, can direct existing human/digital capacity toward higher-propensity accounts, and avoids presuming a new channel is causally superior.</p><div class="note"><b>Important:</b> This is a conditional recommendation for a controlled pilot, not approval to release the entire ₹10 Cr immediately. If leadership requires a single final investment choice today, select <b>better borrower targeting</b> with staged release and explicit stop gates.</div></section><section class="panel"><h2>Planning model and scenario ROI</h2><p>Seven completed months of recovered cash average ₹{base_monthly/1e7:.2f} Cr/month. Simple annualization gives ₹{annualized/1e7:.2f} Cr/year. We assume 70% is targetable, an incremental recovery lift of 5% / 10% / 15%, and 85% of incremental cash is economically realizable after expected displacement, timing and variable-cost haircut. The ₹10 Cr investment is treated as the full program cost.</p><div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Lift assumption</th><th>Gross incremental recovery</th><th>Realized economic benefit</th><th>Planning ROI</th><th>Net benefit after ₹10 Cr</th></tr></thead><tbody>{scenario_rows}</tbody></table></div><p class="formula"><b>Planning ROI</b> = (incremental gross recovery × 85% − ₹10 Cr) / ₹10 Cr. <b>Break-even</b> requires ₹{base.break_even_gross_incremental_recovery_inr/1e7:.2f} Cr gross incremental recovery, equivalent to about {base.break_even_lift_on_targetable_base_pct:.2f}% lift on the assumed targetable cash base.</p><p class="warning">These are sensitivity scenarios, not a causal forecast, confidence interval, or audited business case. Annualization assumes the seven complete months are representative; the source is synthetic and spans less than 12 months. Finance must replace the 70%, 85%, lift and cost assumptions with approved inputs.</p></section><section class="panel"><h2>Investment allocation (single area: better borrower targeting)</h2><div class="allocation"><div><b>₹2.0 Cr</b><span>Data foundation & decisioning integration</span></div><div><b>₹3.0 Cr</b><span>Targeting model, feature store, validation and monitoring</span></div><div><b>₹3.0 Cr</b><span>Controlled pilot operations and treatment capacity</span></div><div><b>₹1.0 Cr</b><span>Experiment measurement, independent QA and Finance reconciliation</span></div><div><b>₹1.0 Cr</b><span>Contingency released only after pilot gate</span></div></div><p class="small">Illustrative budget envelope totaling ₹10 Cr; obtain vendor quotes and Finance approval before commitment. This allocation is not sourced from actual procurement data.</p></section><section class="panel"><h2>Counterfactual design to establish actual ROI</h2><ol><li><b>Eligibility:</b> freeze all eligible accounts before assignment; exclude legal holds, disputes and policy-restricted cases.</li><li><b>Randomize:</b> account-level 50/50 business-as-usual control vs. targeting treatment, stratified by DPD, risk, loan type, balance band and prior contact. Use borrower-level randomization if linked accounts can contaminate arms.</li><li><b>Outcome:</b> 30-day net cash per eligible account after reversals/refunds; keep all assigned accounts in intent-to-treat analysis.</li><li><b>Cost:</b> capture model/platform, channel, agent time, vendor, messaging and support cost by arm. Apply a Finance-approved value/realization factor.</li><li><b>Estimate:</b> treatment-minus-control difference in mean net cash per eligible account with 95% confidence interval; scale to eligible population only after checking balance and mix.</li><li><b>Guardrails:</b> complaints, opt-outs, wrong-party contacts, PTP breakage, contact frequency, fairness by risk/DPD and net cost per incremental rupee.</li></ol><div class="note"><b>Scale rule:</b> release remaining funds only if the lower 95% confidence bound on net benefit is positive, point-estimate ROI clears the approved hurdle, and customer-protection guardrails pass. Otherwise iterate or stop.</div></section><section class="panel"><h2>What is established vs. assumed</h2><div class="table-wrap"><table><tbody><tr><th>Established from files</th><td>Completed-month cash amounts; canonicalization outputs; seven-day channel/payment associations (descriptive only); historical denominator absent.</td></tr><tr><th>Assumed for planning</th><td>70% targetable cash share; 5/10/15% lift scenarios; 85% economic realization; ₹10 Cr total cost and illustrative allocation.</td></tr><tr><th>Must be measured</th><td>Randomized incremental lift, uncertainty interval, intervention cost, true net economic value, complaint impact and actual break-even.</td></tr></tbody></table></div></section><footer>Collections Recovery Analytics · Synthetic dataset · Scenario analysis is not a guarantee or causal finding.</footer></main></body></html>'''
(REPORTS/'investment_business_case.html').write_text(report,encoding='utf-8')
print('Wrote reports/investment_business_case.html')
